import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await initializeDatabase(); // This is where the database initialization happens

  runApp(MyApp());
}

class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Wash Out',
      theme: ThemeData.dark(),
      home: MyHomePage(title: 'Clean Bill'),
    );
  }
}

class MyHomePage extends StatefulWidget {
  final String title;

  const MyHomePage({Key? key, required this.title}) : super(key: key);

  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  late Database db;
  int count = 0;
  List<Map<String, dynamic>> results = [];

  Future<void> initializeDatabase() async {
    var directory = await getDatabasesPath();
    db = await openDatabase(
      '$directory/bills.db',
      onCreate: (database) async {
        await db.execute(
          """
          CREATE TABLE IF NOT EXISTS bills (
            id INTEGER PRIMARY KEY,
            date TEXT,
            amount REAL,
            description TEXT,
            category TEXT
          )
          """,
        );
      },
      version: 1,
    );
  }

  void _addBill(String date, double amount, String description, String category) async {
    final res = await db.insert('bills', {
      'date': date,
      'amount': amount,
      'description': description,
      'category': category,
    });
    setState(() {
      count++;
    });
  }

  void _deleteBill(int index) async {
    await db.delete('bills', where: 'id = ?', whereArgs: [index]);
    setState(() {
      count--;
    });
  }

  Future<void> fetchBills() async {
    final res = await db.query('bills');
    setState(() {
      results = res;
    });
  }

  @override
  void initState() {
    super.initState();
    fetchBills();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.title),
      ),
      body: ListView.builder(
        itemCount: results.length,
        itemBuilder: (context, index) {
          return ListTile(
            leading: Icon(Icons.arrow_circle_down_rounded),
            title: Text(results[index]['date'] ?? ''),
            subtitle: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Expanded(
                      child: Container(
                        padding: EdgeInsets.all(4),
                        decoration: BoxDecoration(
                          color: Colors.grey[300],
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Row(
                          children: [
                            Text("Amount"),
                            SizedBox(width: 8),
                            Text("Rs."),
                          ],
                        ),
                      ),
                    ),
                    IconButton(
                      icon: Icon(Icons.edit), onPressed: () => _editBill(index),
                    ),
                    IconButton(
                      icon: Icon(Icons.delete), onPressed: () => _deleteBill(index),
                    ),
                  ],
                ),
                Text(results[index]['description'] ?? '',
                  style: TextStyle(color: Colors.grey, fontSize: 14),
                ),
                Text("${results[index]['category']}",
                  style: TextStyle(fontSize: 14),
                ),
              ],
            ),
            onTap: () {},
          );
        },
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () => _addBill('2023-09-07', 3.5, 'Wash for twice with laundry powder', 'Laundry'),
        child: Icon(Icons.add),
      ),
    );
  }

  void _editBill(int index) {
    final TextEditingController controller = TextEditingController();

    // Fetch the current bill data from the database
    final Map<String, dynamic> billData = results[index];
    controller.text = billData['date'];

    setState(() {
      controller.value = TextEditingController(text: billData['date']);
    });

    Navigator.push(
      context,
      MaterialPageRoute(builder: (context) => EditBillPage(controller: controller, index: index)),
    );
  }
}

// The EditBillPage widget is used to edit the bill details.
class EditBillPage extends StatefulWidget {
  final TextEditingController controller;
  final int index;

  const EditBillPage({
    Key? key,
    required this.controller,
    required this.index,
  }) : super(key: key);

  @override
  _EditBillPageState createState() => _EditBillPageState();
}

class _EditBillPageState extends State<EditBillPage> {
  final TextEditingController controller = TextEditingController();
  bool editing = false;

  void _submitChanges(String date, double amount, String description, String category) async {
    final int index = widget.index;
    final Map<String, dynamic> updatedData = {'date': date, 'amount': amount, 'description': description, 'category': category};

    // Update the record in the database
    await updateDatabase(updatedData, index);
    setState(() { editing = false; });
    Navigator.of(context).pop(); // Close the dialog
  }

  void updateDatabase(Map<String, dynamic> data, int index) async {
    final db = await database;

    await db.update('bills', data, where: 'id = ?', whereArgs: [index]);
  }

  @override
  void initState() {
    super.initState();
    controller.text = widget.controller.text;
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: Text('Edit Bill'),
      content: Form(
        autovalidateMode: AutovalidateMode.always,
        child: TextFormField(
          controller: controller,
          keyboardType: TextInputType.datetime,
          validator: (value) =>
              value!.isEmpty ? 'Please enter the date' : null,
        ),
      ),
      actions: <Widget>[
        ElevatedButton(
          onPressed: _submitChanges,
          child: Text(editing ? 'Save' : 'Update'),
        ),
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: Text('Cancel'),
        ),
      ],
    );
  }
}
